    insert into public.practice_activities (topic_id, kind, title_en, title_vi, sort_order, status, content)
    select v_topic, 'match_meaning', 'Match the meanings', 'Nối từ với nghĩa tiếng Việt', 45, 'published', '{}'::jsonb
    where not exists (select 1 from public.practice_activities p where p.topic_id = v_topic
